export interface GlossaryTerm {
  slug: string;
  term: string;
  shortDef: string;
  definition: string;
  example?: string;
  relatedTerms?: string[];
  category: "seo" | "content" | "cms" | "analytics" | "ai" | "technical" | "marketing";
}

const T = (t: Omit<GlossaryTerm, "slug">): [string, GlossaryTerm] => {
  const slug = t.term.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return [slug, { slug, ...t }];
};

export const GLOSSARY: Record<string, GlossaryTerm> = Object.fromEntries([
  // === SEO FUNDAMENTALS ===
  T({ term: "SEO", shortDef: "Search engine optimization.", definition: "Search Engine Optimization (SEO) is the practice of improving a website so it ranks higher in search engine results pages (SERPs). It encompasses technical SEO (site speed, crawlability), on-page SEO (content, keywords, metadata), and off-page SEO (backlinks, authority).", example: "A SaaS company publishing blog posts targeting \"best [category] software\" queries is doing SEO.", category: "seo", relatedTerms: ["serp", "keyword", "backlink"] }),
  T({ term: "SERP", shortDef: "Search engine results page.", definition: "A SERP is the page Google (or Bing) shows after a user types a query. Modern SERPs include organic results, ads, featured snippets, People Also Ask boxes, knowledge panels, image carousels, and increasingly AI overviews.", example: "When someone searches \"best headless CMS\", the SERP has 10 organic results, a comparison table, and often an AI overview.", category: "seo" }),
  T({ term: "Keyword", shortDef: "A search query target.", definition: "A keyword is a word or phrase users type into search engines. SEO content is optimized around target keywords (e.g., \"blog title generator\"). Modern SEO emphasizes search intent and topic clusters over single keywords.", category: "seo" }),
  T({ term: "Long-tail keyword", shortDef: "Specific, low-volume search queries.", definition: "Long-tail keywords are longer, more specific queries with lower search volume but higher intent. They're easier to rank for and convert better. Example: \"best headless CMS for Next.js 15\" (long-tail) vs \"CMS\" (head).", category: "seo" }),
  T({ term: "Search intent", shortDef: "What the user is trying to do.", definition: "Search intent is the goal behind a query: informational (learn something), navigational (find a site), commercial (compare options), or transactional (buy now). Google ranks pages that best match intent.", category: "seo" }),
  T({ term: "Featured snippet", shortDef: "Answer box at top of Google.", definition: "A featured snippet is the answer box Google shows above organic results for some queries. It pulls content directly from a page. Ranking in a featured snippet can double your CTR.", category: "seo" }),
  T({ term: "Meta description", shortDef: "Page summary shown in search results.", definition: "A meta description is an HTML tag (around 155 chars) summarizing a page. It appears under the title in SERPs. Not a ranking factor directly, but affects click-through rate.", category: "seo", relatedTerms: ["meta-title", "ctr"] }),
  T({ term: "Meta title", shortDef: "Page title shown in SERPs.", definition: "The meta title (<title> tag) is what shows as the clickable headline in search results. Google may rewrite it. Keep it under 60 chars, include primary keyword near the start.", category: "seo" }),
  T({ term: "Title tag", shortDef: "HTML element for the page title.", definition: "The <title> tag in HTML is one of the strongest on-page SEO signals. It tells search engines and browsers what the page is about.", category: "seo" }),
  T({ term: "H1", shortDef: "The main page heading.", definition: "An <h1> is the main heading of a page. Best practice: exactly one H1 per page that describes the main topic. It's the strongest on-page heading signal for SEO.", category: "seo" }),
  T({ term: "Canonical URL", shortDef: "The preferred URL for a page.", definition: "A canonical URL tells search engines which version of a page is the \"original\" when multiple URLs have similar content. Use <link rel=\"canonical\"> to prevent duplicate content issues.", example: "A product page accessible at both ?sort=new and the default URL should canonical to the default.", category: "seo" }),
  T({ term: "Hreflang", shortDef: "Tells Google which language a page is in.", definition: "Hreflang is an HTML attribute that tells Google which language and region a page targets. Essential for multi-language sites to serve the right version to users.", example: "<link rel=\"alternate\" hreflang=\"fr\" href=\"https://example.com/fr/page\" />", category: "seo" }),
  T({ term: "Backlink", shortDef: "A link from another site to yours.", definition: "A backlink (inbound link) is a link from another website to your site. Backlinks from authoritative sites are one of Google's strongest ranking signals.", category: "seo" }),
  T({ term: "Domain authority", shortDef: "A site's overall ranking strength (Moz metric).", definition: "Domain Authority (DA) is Moz's proprietary score (0-100) predicting how well a site will rank. Google doesn't use DA, but it's a useful proxy for overall SEO strength.", category: "seo" }),
  T({ term: "Page authority", shortDef: "A single page's ranking strength.", definition: "Page Authority (PA) is Moz's per-page score predicting ranking ability. Similar to DA but for individual URLs.", category: "seo" }),
  T({ term: "PageRank", shortDef: "Google's original link-based ranking algorithm.", definition: "PageRank is the algorithm Google was founded on — measuring a page's importance by the links pointing to it. Still part of Google's ranking system, though heavily evolved.", category: "seo" }),
  T({ term: "Internal link", shortDef: "A link between pages on the same site.", definition: "Internal linking is how you connect pages on your own site. Strong internal linking distributes PageRank, helps Google understand site structure, and improves user navigation.", category: "seo" }),
  T({ term: "Anchor text", shortDef: "The clickable text of a link.", definition: "Anchor text is the visible, clickable text of a hyperlink. It gives Google context about the linked page. Exact-match anchors are powerful but can be spammy if overused.", category: "seo" }),
  T({ term: "NoFollow", shortDef: "Tells search engines not to follow/credit a link.", definition: "rel=\"nofollow\" tells search engines not to pass ranking credit through a link. Use on paid, UGC, or untrusted links.", category: "seo" }),
  T({ term: "Schema markup", shortDef: "Structured data for rich results.", definition: "Schema markup (schema.org vocabulary) is structured data that helps search engines understand page content. When added via JSON-LD, it enables rich results like stars, FAQs, and product info.", category: "seo" }),
  T({ term: "JSON-LD", shortDef: "Schema markup format.", definition: "JSON-LD (JavaScript Object Notation for Linked Data) is Google's preferred format for adding schema markup. Added via <script type=\"application/ld+json\">.", category: "seo" }),
  T({ term: "Structured data", shortDef: "Machine-readable page info.", definition: "Structured data is a standardized format for providing information about a page and classifying its content — typically via schema.org markup.", category: "seo" }),
  T({ term: "Rich results", shortDef: "Enhanced SERP listings.", definition: "Rich results (formerly rich snippets) are visually enhanced search listings — star ratings, prices, FAQs, videos, and more. Triggered by structured data.", category: "seo" }),
  T({ term: "Robots.txt", shortDef: "File telling crawlers what to access.", definition: "robots.txt is a text file at your site root that tells search engine crawlers which pages they can or cannot crawl. Not a security measure — just a politeness request.", category: "seo" }),
  T({ term: "XML sitemap", shortDef: "List of site URLs for crawlers.", definition: "An XML sitemap is a file listing all your site's URLs to help search engines discover them. Submit it in Google Search Console for faster indexing.", category: "seo" }),
  T({ term: "Crawl budget", shortDef: "How many pages Google will crawl per visit.", definition: "Crawl budget is the number of URLs Googlebot will crawl on your site within a given timeframe. Large sites need to optimize which pages Google spends time on.", category: "seo" }),
  T({ term: "Indexation", shortDef: "Getting pages into Google's index.", definition: "Indexation is the process of Google storing your pages in its index. A page has to be indexed to rank. Check index status in Google Search Console.", category: "seo" }),
  T({ term: "Google Search Console", shortDef: "Google's webmaster tools.", definition: "Google Search Console (GSC) is Google's free tool for monitoring your site's presence in Google search. Submit sitemaps, fix errors, see queries, and track impressions/clicks.", category: "seo" }),
  T({ term: "Core Web Vitals", shortDef: "Google's user experience metrics.", definition: "Core Web Vitals are three metrics Google uses as a ranking factor: LCP (loading), INP (interactivity), and CLS (visual stability). Measured in Google Search Console.", category: "technical" }),
  T({ term: "LCP", shortDef: "Largest contentful paint — page load metric.", definition: "Largest Contentful Paint (LCP) is the time from page load start until the largest image/text block is visible. Good: <2.5s. Poor: >4s.", category: "technical" }),
  T({ term: "CLS", shortDef: "Cumulative layout shift — visual stability metric.", definition: "Cumulative Layout Shift (CLS) measures how much content jumps around during page load. Good: <0.1. Reserve space for images/ads to improve.", category: "technical" }),
  T({ term: "INP", shortDef: "Interaction to next paint — responsiveness metric.", definition: "Interaction to Next Paint (INP) measures how quickly a page responds to user interactions. Replaced FID in 2024. Good: <200ms.", category: "technical" }),
  T({ term: "TTFB", shortDef: "Time to first byte — server response speed.", definition: "Time to First Byte (TTFB) is how long the browser waits before receiving the first byte from the server. Good: <800ms. Affects LCP directly.", category: "technical" }),

  // === CONTENT MARKETING ===
  T({ term: "Content marketing", shortDef: "Creating content to attract customers.", definition: "Content marketing is a strategy of creating and distributing valuable content (blogs, videos, podcasts) to attract and convert customers. More sustainable than paid ads but takes longer.", category: "marketing" }),
  T({ term: "Pillar page", shortDef: "In-depth guide on a broad topic.", definition: "A pillar page is a long-form (3000+ word) guide covering a broad topic comprehensively. Supporting cluster content links to it, creating a topic cluster for SEO.", category: "content" }),
  T({ term: "Topic cluster", shortDef: "Group of related pages linked to a pillar.", definition: "A topic cluster is a pillar page plus multiple supporting articles (cluster content) all internally linked. This structure signals topical authority to Google.", category: "content" }),
  T({ term: "Evergreen content", shortDef: "Content that stays relevant for years.", definition: "Evergreen content is content that remains relevant and useful over time — like \"how to write a blog post\" vs \"best blog tools 2023\". Highest ROI type of content.", category: "content" }),
  T({ term: "Skyscraper content", shortDef: "Longer, better version of top-ranking content.", definition: "The Skyscraper Technique (Brian Dean) involves finding the top-ranking content for a keyword and creating a significantly better, longer, more comprehensive version.", category: "content" }),
  T({ term: "Content calendar", shortDef: "Schedule of planned content.", definition: "A content calendar is a schedule showing what content will be published when. Helps coordinate topics, keywords, and team workflows.", category: "content" }),
  T({ term: "Editorial calendar", shortDef: "Content calendar for a publication.", definition: "An editorial calendar is a more detailed content calendar for media operations — includes assignees, reviewers, publish dates, topic clusters, and approval stages.", category: "content" }),
  T({ term: "Content gap analysis", shortDef: "Finding topics competitors rank for but you don't.", definition: "Content gap analysis identifies keywords competitors rank for that you don't. Fill the gaps to steal their traffic. Tools: Ahrefs, Semrush, or RankFlo's competitive analysis.", category: "content" }),
  T({ term: "Content pruning", shortDef: "Deleting or improving low-performing content.", definition: "Content pruning is the practice of removing or consolidating underperforming pages. Helps crawl budget, focuses authority on remaining pages, and improves overall site quality.", category: "content" }),
  T({ term: "Listicle", shortDef: "A numbered list article.", definition: "A listicle (list + article) is a post structured as a numbered list — \"10 ways to…\", \"Top 25 X\". Highly shareable, often rank well for \"best of\" queries.", category: "content" }),
  T({ term: "How-to content", shortDef: "Step-by-step instructional content.", definition: "How-to content teaches readers to accomplish a task. Highly valuable for SEO — targets \"how to X\" queries which are massive in volume.", category: "content" }),
  T({ term: "Pillar-and-cluster", shortDef: "Content strategy built on topic authority.", definition: "Pillar-and-cluster is a content model: one pillar page broadly covers a topic, cluster pages go deep on subtopics, and all internally link. Signals topical authority.", category: "content" }),

  // === CMS / TECHNICAL ===
  T({ term: "CMS", shortDef: "Content management system.", definition: "A Content Management System (CMS) is software for creating, managing, and publishing digital content without coding. Examples: WordPress, Ghost, Contentful, RankFlo.", category: "cms" }),
  T({ term: "Headless CMS", shortDef: "CMS with API, no front-end rendering.", definition: "A headless CMS separates content management from front-end rendering. Content lives in the CMS, but any frontend (Next.js, React, mobile app) consumes it via API.", example: "Contentful, Sanity, RankFlo, and Strapi are headless CMSs.", category: "cms" }),
  T({ term: "Hybrid CMS", shortDef: "Combines headless + traditional rendering.", definition: "A hybrid CMS offers both: API access (like headless) AND built-in themes/rendering (like traditional). Gives flexibility with less upfront work. RankFlo is a hybrid CMS.", category: "cms" }),
  T({ term: "Static site generator", shortDef: "Builds HTML files at deploy time.", definition: "A Static Site Generator (SSG) builds your site as static HTML/CSS/JS at deploy time. No server at runtime. Examples: Hugo, Jekyll, Astro, Next.js static export.", category: "cms" }),
  T({ term: "Jamstack", shortDef: "Modern web architecture (JavaScript, APIs, Markup).", definition: "Jamstack is an architecture philosophy: prebuilt Markup delivered via CDN, with dynamic features via JavaScript and APIs. Fast, secure, cheap to host.", category: "cms" }),
  T({ term: "API-first", shortDef: "API is the primary interface.", definition: "API-first means the software is designed around its API rather than a UI. Any frontend can consume it. RankFlo is API-first.", category: "cms" }),
  T({ term: "Multi-tenant", shortDef: "One app serves multiple isolated customers.", definition: "Multi-tenant software serves multiple organizations from a single instance, with data isolation between them. RankFlo is multi-tenant — each organization's content is isolated.", category: "cms" }),
  T({ term: "Multi-site", shortDef: "One installation manages multiple websites.", definition: "Multi-site CMSs let one installation manage multiple distinct websites. Useful for agencies managing multiple client blogs or brands.", category: "cms" }),
  T({ term: "RBAC", shortDef: "Role-based access control.", definition: "Role-Based Access Control (RBAC) gives users permissions based on their role (admin, editor, author, viewer). Essential for team CMSs.", category: "cms" }),
  T({ term: "Webhooks", shortDef: "HTTP callbacks for events.", definition: "Webhooks are HTTP callbacks that fire when events happen in a system. E.g., a CMS can fire a webhook to trigger your static site to rebuild on publish.", category: "technical" }),
  T({ term: "Incremental static regeneration", shortDef: "Rebuild individual pages on-demand.", definition: "Incremental Static Regeneration (ISR) is a Next.js feature that regenerates individual static pages on-demand when content changes, without rebuilding the whole site.", category: "technical" }),
  T({ term: "Static site generation", shortDef: "Pre-build all pages as HTML.", definition: "Static Site Generation (SSG) pre-builds all pages as HTML at build time. Maximum performance and cacheability, but rebuilds needed for content changes.", category: "technical" }),
  T({ term: "Server-side rendering", shortDef: "Render HTML on the server per request.", definition: "Server-Side Rendering (SSR) renders HTML on the server for each request. Good for dynamic content. Slower than SSG but always fresh.", category: "technical" }),
  T({ term: "Client-side rendering", shortDef: "JavaScript renders HTML in the browser.", definition: "Client-Side Rendering (CSR) ships empty HTML + JS; the browser renders the content. Bad for SEO unless hydrated with SSR first. Common in single-page apps.", category: "technical" }),
  T({ term: "React Server Components", shortDef: "React components that run only on the server.", definition: "React Server Components (RSC) run exclusively on the server — no JS shipped to the browser. Next.js App Router uses RSC by default. Great for SEO + performance.", category: "technical" }),
  T({ term: "Edge computing", shortDef: "Compute at the network edge, close to users.", definition: "Edge computing runs code close to users geographically (via CDN PoPs). Faster than centralized servers. Examples: Vercel Edge Runtime, Cloudflare Workers.", category: "technical" }),
  T({ term: "CDN", shortDef: "Content delivery network.", definition: "A CDN is a network of servers worldwide that cache your site's content close to users. Reduces latency. Examples: Cloudflare, Vercel, Fastly.", category: "technical" }),
  T({ term: "Tiptap", shortDef: "Rich-text editor framework for React/Vue.", definition: "Tiptap is a headless editor framework built on ProseMirror. Used by RankFlo, Notion-like tools, and many modern CMSs for rich-text content editing.", category: "technical" }),
  T({ term: "ProseMirror", shortDef: "Editor toolkit underlying Tiptap.", definition: "ProseMirror is a toolkit for building rich-text editors with custom schemas. Tiptap is a React wrapper around it.", category: "technical" }),
  T({ term: "Markdown", shortDef: "Lightweight markup language.", definition: "Markdown is a plain-text format for writing with formatting (# for headings, ** for bold). Renders to HTML. Popular in developer blogs and README files.", category: "technical" }),
  T({ term: "MDX", shortDef: "Markdown + JSX components.", definition: "MDX lets you use JSX components inside Markdown. Popular in developer docs where you want interactive components embedded in prose content.", category: "technical" }),

  // === ANALYTICS ===
  T({ term: "Bounce rate", shortDef: "Percentage of single-page visits.", definition: "Bounce rate is the percentage of sessions where a user views only one page before leaving. High bounce rate can signal bad content match or UX issues — but it's complicated.", category: "analytics" }),
  T({ term: "CTR", shortDef: "Click-through rate.", definition: "Click-Through Rate (CTR) is the percentage of impressions that result in clicks. In SEO, it's the ratio of SERP clicks to impressions. Ads, emails, and buttons also have CTR.", category: "analytics" }),
  T({ term: "Impressions", shortDef: "Number of times content was shown.", definition: "Impressions count how many times your content appeared to users — in search results, ads, or feeds. Not the same as views (which require actual engagement).", category: "analytics" }),
  T({ term: "Page views", shortDef: "Number of times a page was loaded.", definition: "Page views count how many times a page was loaded. Different from unique visitors (one visitor can create multiple page views).", category: "analytics" }),
  T({ term: "Sessions", shortDef: "A user's visit to your site.", definition: "A session is a group of user interactions on your site within a time window (typically 30 minutes). One user can have multiple sessions. Used in analytics like GA4.", category: "analytics" }),
  T({ term: "Cookieless analytics", shortDef: "Analytics without browser cookies.", definition: "Cookieless analytics tracks visitors without setting cookies — respecting privacy and GDPR. Examples: Plausible, Fathom, RankFlo's built-in analytics.", category: "analytics" }),

  // === AI / LLM ===
  T({ term: "GEO", shortDef: "Generative engine optimization.", definition: "Generative Engine Optimization (GEO) is SEO for AI answer engines like ChatGPT, Perplexity, and Claude. Focuses on getting cited in AI-generated answers, not just ranking in Google.", category: "ai" }),
  T({ term: "LLM", shortDef: "Large language model.", definition: "A Large Language Model (LLM) is an AI trained on massive text corpora to generate human-like text. Examples: GPT-5, Claude 4.7 Opus, Gemini 2.5.", category: "ai" }),
  T({ term: "RAG", shortDef: "Retrieval-augmented generation.", definition: "Retrieval-Augmented Generation (RAG) is an AI technique where a model retrieves relevant documents before generating an answer. Used by Perplexity, ChatGPT web search, and many enterprise LLM apps.", category: "ai" }),
  T({ term: "llms.txt", shortDef: "Spec for giving LLMs structured site info.", definition: "llms.txt is a proposed standard (similar to robots.txt) that gives LLMs a structured, markdown-formatted summary of your site. Helps AI crawlers cite you correctly.", category: "ai" }),
  T({ term: "AI overview", shortDef: "Google's AI-generated answers in SERPs.", definition: "AI Overviews (formerly SGE) are Google's AI-generated answers at the top of search results. Changes SEO — clicks may drop unless your content gets cited.", category: "ai" }),
  T({ term: "ChatGPT", shortDef: "OpenAI's flagship AI chatbot.", definition: "ChatGPT is OpenAI's AI chatbot powered by GPT models. Handles text generation, coding, research, and more. Now a major source of traffic for publishers via citations.", category: "ai" }),
  T({ term: "Claude", shortDef: "Anthropic's AI assistant.", definition: "Claude is Anthropic's AI assistant. The Claude 4.X family — Opus 4.7, Sonnet 4.6, Haiku 4.5 — is known for long context windows (up to 1M tokens) and strong reasoning.", category: "ai" }),
  T({ term: "Perplexity", shortDef: "AI-powered search engine.", definition: "Perplexity is an AI search engine that answers queries with citations to source websites. A major traffic driver for content sites that get cited.", category: "ai" }),
  T({ term: "Prompt engineering", shortDef: "Writing effective prompts for LLMs.", definition: "Prompt engineering is the art of writing instructions to LLMs to get desired outputs. Key skill for using ChatGPT, Claude, or building AI features.", category: "ai" }),
  T({ term: "Hallucination", shortDef: "AI making up incorrect information.", definition: "An AI hallucination is when an LLM generates confident-sounding but incorrect or fabricated information. Mitigated by RAG, citations, and careful prompting.", category: "ai" }),
  T({ term: "Context window", shortDef: "How much text an LLM can process at once.", definition: "Context window is the maximum amount of text (in tokens) an LLM can process in a single conversation. Claude Opus 4.7 supports 1M tokens. GPT-5 supports up to 200k.", category: "ai" }),
  T({ term: "Embedding", shortDef: "Numerical vector representing text meaning.", definition: "An embedding is a numerical vector representing a piece of text's semantic meaning. Used for similarity search, RAG, and recommendation systems.", category: "ai" }),
  T({ term: "Semantic search", shortDef: "Search based on meaning, not keywords.", definition: "Semantic search matches queries to documents based on meaning (via embeddings) rather than exact keyword matches. What modern AI-powered search uses.", category: "ai" }),

  // === MORE SEO DETAILS ===
  T({ term: "301 redirect", shortDef: "Permanent redirect.", definition: "A 301 redirect is an HTTP response permanently redirecting one URL to another. Passes ~90-99% of link equity. Use when permanently moving content.", category: "seo" }),
  T({ term: "302 redirect", shortDef: "Temporary redirect.", definition: "A 302 redirect is a temporary URL redirect. Generally doesn't pass link equity. Use 301 unless the move is truly temporary.", category: "seo" }),
  T({ term: "Breadcrumbs", shortDef: "Navigation showing page hierarchy.", definition: "Breadcrumbs are a navigation aid showing a page's hierarchy (e.g., Home > Blog > Category > Post). Can also be a structured data schema for rich results.", category: "seo" }),
  T({ term: "Alt text", shortDef: "Image description for accessibility + SEO.", definition: "Alt text describes an image for screen readers and when images fail to load. Also helps image SEO — Google uses alt text to understand images.", category: "seo" }),
  T({ term: "Open Graph", shortDef: "Meta tags controlling social share cards.", definition: "Open Graph (OG) is a protocol (from Facebook) using meta tags to control how URLs appear when shared on social media. og:title, og:description, og:image are the main ones.", category: "seo" }),
  T({ term: "OG image", shortDef: "Image shown in social share cards.", definition: "An Open Graph image (og:image) is the thumbnail shown when your URL is shared on social. Recommended: 1200×630 pixels. Dynamically generated OG images are increasingly common.", category: "seo" }),
  T({ term: "Twitter card", shortDef: "Twitter's social share card format.", definition: "Twitter Cards are Twitter's format for rich share previews. twitter:card, twitter:title, etc. Usually summary_large_image uses the same image as OG.", category: "seo" }),
  T({ term: "Favicon", shortDef: "Small icon shown in browser tabs.", definition: "A favicon is the small icon shown in browser tabs and bookmarks. Modern sites should provide multiple sizes for different devices and contexts.", category: "seo" }),
  T({ term: "Keyword density", shortDef: "% of page text that's a target keyword.", definition: "Keyword density is the percentage of page text made up of a target keyword. 1-2% is a rough guideline. Excessive density triggers keyword stuffing penalties.", category: "seo" }),
  T({ term: "Keyword stuffing", shortDef: "Over-using keywords unnaturally.", definition: "Keyword stuffing is the practice of repeating keywords unnaturally to manipulate rankings. Penalized by Google. Write naturally — focus on semantic relevance.", category: "seo" }),
  T({ term: "Cloaking", shortDef: "Showing different content to crawlers vs users.", definition: "Cloaking is showing different content to search engine crawlers than to human users to manipulate rankings. Violates Google's guidelines — will get you penalized.", category: "seo" }),
  T({ term: "E-E-A-T", shortDef: "Experience, Expertise, Authoritativeness, Trust.", definition: "E-E-A-T is Google's quality framework: Experience, Expertise, Authoritativeness, and Trustworthiness. Important for YMYL topics. Signal it via author pages, citations, and credentials.", category: "seo" }),
  T({ term: "YMYL", shortDef: "Your Money, Your Life topics.", definition: "YMYL (Your Money or Your Life) is Google's classification for topics affecting users' wellbeing — finance, health, legal. Held to higher quality standards.", category: "seo" }),
  T({ term: "Core update", shortDef: "Broad change to Google's ranking algorithm.", definition: "A core update is Google's periodic broad adjustment to its ranking algorithm. Can cause significant ranking changes. Not targeting specific sites — just re-evaluating content quality.", category: "seo" }),
  T({ term: "Google Panda", shortDef: "2011 update targeting low-quality content.", definition: "Google Panda was a 2011 algorithm update targeting thin/low-quality content. Now part of core algorithm. Inspired focus on content quality.", category: "seo" }),
  T({ term: "Google Penguin", shortDef: "2012 update targeting spammy links.", definition: "Google Penguin was a 2012 algorithm update targeting manipulative link building. Also now part of the core algorithm. Ushered in the era of safer link strategies.", category: "seo" }),
  T({ term: "Helpful Content Update", shortDef: "Google's 2022 content quality update.", definition: "Google's Helpful Content Update (2022) targets sites with large amounts of unhelpful, AI-generated, or SEO-first (rather than user-first) content.", category: "seo" }),

  // === MORE CMS / TECH ===
  T({ term: "Monolith CMS", shortDef: "Tightly coupled CMS + frontend.", definition: "A monolith CMS combines content management and front-end rendering tightly (e.g., WordPress). Simple to set up but hard to customize and slow compared to headless architectures.", category: "cms" }),
  T({ term: "Decoupled CMS", shortDef: "Separated backend + presentation.", definition: "A decoupled CMS separates the backend (content management) from the presentation layer (frontend). Similar to headless but with optional built-in rendering.", category: "cms" }),
  T({ term: "Git-based CMS", shortDef: "CMS where content lives in a git repo.", definition: "A git-based CMS stores content in a git repository (often as Markdown). Examples: Netlify CMS, Tina, Forestry. Good for developer blogs, limited for non-technical authors.", category: "cms" }),
  T({ term: "Content federation", shortDef: "Combining content from multiple sources.", definition: "Content federation combines content from multiple sources (different CMSs, databases, APIs) into one unified content layer. Used by large enterprises like Hygraph.", category: "cms" }),
  T({ term: "Content modeling", shortDef: "Defining content structure.", definition: "Content modeling is the process of defining content types, fields, and relationships in a CMS (e.g., \"a Blog Post has a title, author, tags\"). Foundation of any CMS implementation.", category: "cms" }),
  T({ term: "Block editor", shortDef: "Editor where content is in blocks.", definition: "A block editor treats each piece of content (paragraph, image, heading) as a discrete block. Popularized by Gutenberg (WordPress), Notion, and Tiptap. Default in modern CMSs.", category: "cms" }),
  T({ term: "WYSIWYG", shortDef: "What You See Is What You Get editor.", definition: "WYSIWYG (what you see is what you get) editors show formatted content as it will appear on the live site. Modern CMSs use block editors instead, which are more structured.", category: "cms" }),

  // === MARKETING ===
  T({ term: "CTA", shortDef: "Call to action.", definition: "A Call To Action (CTA) is a prompt telling users what to do next — \"Sign up\", \"Download\", \"Learn more\". Good CTAs are specific, action-oriented, and visually prominent.", category: "marketing" }),
  T({ term: "Lead magnet", shortDef: "Free offer in exchange for an email.", definition: "A lead magnet is a free resource (ebook, template, guide) offered in exchange for an email address. Core tool in content marketing for list building.", category: "marketing" }),
  T({ term: "Conversion rate", shortDef: "% of visitors who take a desired action.", definition: "Conversion rate is the percentage of visitors who take a desired action (sign up, purchase, download). Key SaaS metric.", category: "marketing" }),
  T({ term: "Funnel", shortDef: "Path from visitor to customer.", definition: "A marketing funnel is the journey from first visit to customer — awareness → interest → consideration → purchase. Measure drop-off at each stage.", category: "marketing" }),
  T({ term: "Inbound marketing", shortDef: "Attract customers via helpful content.", definition: "Inbound marketing is a methodology of attracting customers by creating valuable content and experiences tailored to them — instead of interrupting them with ads.", category: "marketing" }),
  T({ term: "Product-led growth", shortDef: "Product itself drives adoption.", definition: "Product-Led Growth (PLG) uses the product itself as the primary driver of user acquisition, conversion, and expansion. Typically via free tiers, self-serve signup, and viral features.", category: "marketing" }),

  // === MORE SEO ===
  T({ term: "On-page SEO", shortDef: "Optimizations on the page itself.", definition: "On-page SEO covers everything you control on a single page: title tag, meta description, headings, content quality, internal linking, image alt text, and structured data. Strong on-page SEO is table stakes for ranking.", category: "seo" }),
  T({ term: "Off-page SEO", shortDef: "Signals from outside your site.", definition: "Off-page SEO covers signals Google reads from outside your site — backlinks, brand mentions, social signals, and reviews. Backlinks are still the strongest off-page signal.", category: "seo" }),
  T({ term: "Technical SEO", shortDef: "Crawlability, indexability, performance.", definition: "Technical SEO covers everything that helps search engines crawl, render, and index your site: site speed, sitemaps, robots.txt, canonical tags, hreflang, mobile-friendliness, structured data, and HTTPS.", category: "seo" }),
  T({ term: "Local SEO", shortDef: "Ranking for location-based queries.", definition: "Local SEO is the practice of ranking for queries with location intent (e.g. \"plumber near me\"). Centers on Google Business Profile, NAP consistency, local citations, and reviews.", category: "seo" }),
  T({ term: "International SEO", shortDef: "Targeting users in different countries/languages.", definition: "International SEO uses hreflang tags, country/language URL structures (ccTLDs, subdomains, or subdirectories), and localized content to rank in multiple regions.", category: "seo" }),
  T({ term: "E-E-A-T", shortDef: "Experience, Expertise, Authoritativeness, Trustworthiness.", definition: "E-E-A-T is Google's framework for evaluating content quality, especially for YMYL topics. The first E (Experience) was added in 2022 — Google rewards content from people who have lived experience with the topic.", category: "seo" }),
  T({ term: "YMYL", shortDef: "Your Money or Your Life topics.", definition: "YMYL pages can impact health, finance, safety, or major life decisions. Google holds them to higher quality standards (E-E-A-T). Examples: medical advice, investment, legal, news.", category: "seo" }),
  T({ term: "Helpful content update", shortDef: "Google update targeting unhelpful content.", definition: "The Helpful Content Update (rolling since Aug 2022) demotes content written for search engines rather than people. Sites with mostly thin/SEO-spam content can see site-wide ranking drops.", category: "seo" }),
  T({ term: "Core update", shortDef: "Major change to Google's ranking algorithm.", definition: "Core updates are broad changes to Google's ranking algorithm, rolled out a few times per year. They can cause significant ranking shifts. The fix is rarely a single tactic — focus on content quality and E-E-A-T.", category: "seo" }),
  T({ term: "RankBrain", shortDef: "Google's machine-learning ranking signal.", definition: "RankBrain is a machine-learning system Google uses to interpret queries and improve ranking. Launched in 2015, it helps Google understand never-before-seen queries.", category: "seo" }),
  T({ term: "BERT", shortDef: "Google's NLP model for understanding queries.", definition: "BERT (Bidirectional Encoder Representations from Transformers) is the natural language model Google deployed in 2019 to better understand the context of search queries — especially conversational and long-tail queries.", category: "seo" }),
  T({ term: "MUM", shortDef: "Google's multimodal AI for complex queries.", definition: "MUM (Multitask Unified Model) is Google's AI model launched in 2021 for handling complex, multimodal queries — combining text, images, and multiple languages.", category: "seo" }),
  T({ term: "Knowledge graph", shortDef: "Google's database of entities and relationships.", definition: "The Knowledge Graph is Google's database connecting people, places, things, and concepts. Powers knowledge panels, rich answers, and entity-based search.", category: "seo" }),
  T({ term: "Topical authority", shortDef: "Recognition as a domain expert on a topic.", definition: "Topical authority is built by publishing comprehensive, interconnected content on a specific topic. Sites with topical authority rank for related queries even with fewer backlinks.", category: "seo", relatedTerms: ["pillar-page", "topic-cluster"] }),
  T({ term: "Entity SEO", shortDef: "Optimizing for entities, not just keywords.", definition: "Entity SEO is the practice of optimizing for entities (people, places, things, concepts) recognized by Google's Knowledge Graph — going beyond keyword matching toward semantic understanding.", category: "seo" }),
  T({ term: "Pogo-sticking", shortDef: "User clicks a result and bounces back fast.", definition: "Pogo-sticking is when a user clicks a search result, doesn't find what they want, and quickly returns to the SERP to click another result. Strong negative signal to Google.", category: "seo" }),
  T({ term: "Dwell time", shortDef: "How long a user stays on a page from search.", definition: "Dwell time is the time a user spends on a page after clicking from a SERP, before returning. Long dwell time signals satisfaction; short dwell time may suggest poor content match.", category: "seo" }),
  T({ term: "CTR", shortDef: "Click-through rate on a SERP.", definition: "CTR (Click-Through Rate) is the percentage of users who click your result after seeing it in search. Improve via better titles, meta descriptions, and structured data.", category: "seo" }),
  T({ term: "301 redirect", shortDef: "Permanent redirect.", definition: "A 301 redirect tells browsers and search engines a page has permanently moved. Passes most ranking signal (\"link equity\") to the new URL. Use when permanently changing a URL.", category: "seo" }),
  T({ term: "302 redirect", shortDef: "Temporary redirect.", definition: "A 302 redirect signals a temporary move. Passes less ranking signal than 301. Use for A/B tests, geo-redirects, or genuinely temporary states.", category: "seo" }),
  T({ term: "404 error", shortDef: "Page not found.", definition: "A 404 status code tells browsers and crawlers that the requested URL doesn't exist. Common, harmless. The problem is when expected pages return 404 unexpectedly.", category: "technical" }),
  T({ term: "Soft 404", shortDef: "Page that says \"not found\" but returns 200.", definition: "A soft 404 is a page that displays a \"not found\" message but returns HTTP 200. Google penalizes these — pages should return real 404 status codes.", category: "seo" }),
  T({ term: "Mobile-first indexing", shortDef: "Google indexes the mobile version of your site.", definition: "Since 2019, Google primarily uses the mobile version of your site for indexing and ranking. If your mobile site is missing content or links, those won't be ranked.", category: "seo" }),
  T({ term: "Page experience", shortDef: "Ranking signal combining UX metrics.", definition: "Page experience is a Google ranking signal combining Core Web Vitals, mobile-friendliness, HTTPS, and absence of intrusive interstitials.", category: "seo" }),
  T({ term: "AMP", shortDef: "Accelerated Mobile Pages.", definition: "AMP is a Google-backed framework for building extremely fast mobile pages. Lost importance after Google removed AMP requirements from Top Stories in 2021. Most publishers have moved off AMP.", category: "technical" }),
  T({ term: "Sitelinks", shortDef: "Sub-page links shown in Google results.", definition: "Sitelinks are the additional links Google shows below a top-ranking result, leading to important pages on the same site. Generated automatically; you can demote (but not force) specific sitelinks.", category: "seo" }),
  T({ term: "Breadcrumb", shortDef: "Navigation showing page hierarchy.", definition: "Breadcrumbs show users (and Google) where a page sits in the site hierarchy. Add BreadcrumbList JSON-LD for rich result eligibility.", category: "seo" }),
  T({ term: "Faceted navigation", shortDef: "Filters that create URL parameters.", definition: "Faceted navigation lets users filter results (e.g. by color, size). Each filter combination creates a unique URL — a major source of duplicate content and crawl budget waste if not handled with canonicals or robots rules.", category: "seo" }),
  T({ term: "Helpful Content System", shortDef: "Google's ongoing quality signal.", definition: "The Helpful Content System (formerly Helpful Content Update) is now part of Google's core ranking system, evaluating whether content is genuinely useful for people.", category: "seo" }),
  T({ term: "Search volume", shortDef: "How many times a keyword is searched per month.", definition: "Search volume is the average monthly search count for a keyword. Tools like Ahrefs, Semrush, and Google Keyword Planner provide estimates. High volume = more potential traffic.", category: "seo" }),
  T({ term: "Keyword difficulty", shortDef: "How hard a keyword is to rank for.", definition: "Keyword difficulty (KD) is a 0–100 score estimating how hard it would be to rank in the top 10 for a keyword. Based on backlink profile of current ranking pages. Different tools score differently.", category: "seo" }),

  // === MORE CONTENT ===
  T({ term: "Listicle", shortDef: "Article structured as a numbered list.", definition: "A listicle is an article structured as a numbered or bulleted list (e.g. \"10 best CMS platforms\"). Easy to skim, great for SEO, and converts well — especially for comparison content.", category: "content" }),
  T({ term: "How-to article", shortDef: "Step-by-step instructional content.", definition: "A how-to article is structured around clear, sequential steps. Eligible for HowTo schema and \"How To\" rich results. High intent for users in problem-solving mode.", category: "content" }),
  T({ term: "Case study", shortDef: "Detailed analysis of a specific success.", definition: "A case study tells the story of a customer or project — challenge, solution, results. Strong for B2B SaaS marketing as social proof.", category: "content" }),
  T({ term: "White paper", shortDef: "In-depth report on a specific topic.", definition: "A white paper is a long-form, authoritative report (often 5–20 pages) on a specific industry topic. Common B2B lead magnet — gated behind an email form.", category: "content" }),
  T({ term: "Content audit", shortDef: "Reviewing existing content for performance.", definition: "A content audit is a systematic review of your existing content — identifying top performers, underperformers, outdated pieces, and gaps. Inputs your content strategy.", category: "content" }),
  T({ term: "Content pruning", shortDef: "Deleting or merging low-value content.", definition: "Content pruning is removing or consolidating thin, outdated, or redundant content. Can lift overall site quality signals to Google. Be careful — don't delete pages with backlinks without redirecting.", category: "content" }),
  T({ term: "Keyword cannibalization", shortDef: "Multiple pages competing for the same keyword.", definition: "Keyword cannibalization happens when multiple pages on your site target the same keyword, splitting ranking signals. Fix by consolidating, redirecting, or differentiating intent.", category: "seo" }),
  T({ term: "Content repurposing", shortDef: "Reusing content in different formats.", definition: "Content repurposing is taking a piece of content and adapting it for different formats or channels (blog → video → tweet thread → podcast). Multiplies reach without proportional effort.", category: "content" }),
  T({ term: "Content syndication", shortDef: "Republishing content on third-party sites.", definition: "Content syndication is republishing your content (or a version of it) on other sites — Medium, LinkedIn, partner publications. Use canonical tags to prevent duplicate content issues.", category: "content" }),
  T({ term: "Buyer guide", shortDef: "Educational content helping users choose a product.", definition: "Buyer guides help users compare options before purchasing. High commercial intent — these pages rank for \"best X\" and \"X vs Y\" queries and drive strong conversion.", category: "content" }),

  // === MORE CMS ===
  T({ term: "Coupled CMS", shortDef: "Traditional CMS where backend and frontend are tied.", definition: "A coupled CMS (like WordPress in default mode) tightly couples the content backend with the frontend rendering. Easy to set up, but limits frontend flexibility.", category: "cms" }),
  T({ term: "Decoupled CMS", shortDef: "Backend and frontend are separated.", definition: "A decoupled CMS separates the content backend from the frontend rendering, but still ships a default frontend. Sits between coupled (WordPress) and headless (Contentful, RankFlo).", category: "cms" }),
  T({ term: "Hybrid CMS", shortDef: "Headless CMS that also offers a frontend layer.", definition: "A hybrid CMS provides headless APIs but also offers visual editing or page-building features. Aimed at marketing teams who want flexibility without forcing developers into pure API-first work.", category: "cms" }),
  T({ term: "Static site generator", shortDef: "Tool that builds HTML at build time.", definition: "A static site generator (SSG) builds HTML pages at build time from content sources. Examples: Astro, Hugo, Jekyll, Eleventy, Next.js (in static mode). Pairs well with headless CMSes.", category: "cms" }),
  T({ term: "JAMstack", shortDef: "JavaScript, APIs, Markup architecture.", definition: "JAMstack is an architecture pattern: pre-rendered Markup served from CDN, JavaScript for dynamic features, APIs for backend. Powered by tools like Next.js, Astro, Gatsby, plus headless CMSes.", category: "cms" }),
  T({ term: "ISR", shortDef: "Incremental static regeneration.", definition: "ISR (Incremental Static Regeneration) is a Next.js feature that lets static pages revalidate in the background — getting both static performance and fresh content.", category: "technical" }),
  T({ term: "SSR", shortDef: "Server-side rendering.", definition: "SSR (Server-Side Rendering) renders HTML on the server for each request. Slower than static, but always fresh. Trade-offs: load on the server, dynamic content.", category: "technical" }),
  T({ term: "SSG", shortDef: "Static site generation.", definition: "SSG (Static Site Generation) renders all HTML at build time. Fastest possible delivery, lowest cost. Trade-off: rebuild needed when content changes.", category: "technical" }),
  T({ term: "CSR", shortDef: "Client-side rendering.", definition: "CSR (Client-Side Rendering) renders content in the browser via JavaScript. Bad for SEO without extra steps (SSR fallback or pre-rendering).", category: "technical" }),
  T({ term: "Edge rendering", shortDef: "Rendering at CDN edge nodes.", definition: "Edge rendering executes code on CDN edge servers (e.g. Vercel Edge, Cloudflare Workers) — faster than origin SSR, can personalize per user with low latency.", category: "technical" }),

  // === MORE ANALYTICS ===
  T({ term: "Engagement rate", shortDef: "% of sessions with meaningful interaction.", definition: "Engagement rate (GA4) is the percentage of sessions that lasted longer than 10 seconds, fired a conversion, or had multiple page views. Replaced bounce rate as the default GA4 metric.", category: "analytics" }),
  T({ term: "Time on page", shortDef: "How long a user stays on a single page.", definition: "Time on page is the duration between a user landing on a page and their next action. Hard to measure for the last page in a session — most tools approximate.", category: "analytics" }),
  T({ term: "Direct traffic", shortDef: "Visitors who arrive without a referrer.", definition: "Direct traffic is visitors who type your URL directly, use a bookmark, or whose referrer was lost (HTTP→HTTPS, certain apps). Often a catch-all for untracked sources.", category: "analytics" }),
  T({ term: "Referral traffic", shortDef: "Visitors arriving from links on other sites.", definition: "Referral traffic is visitors who clicked a link on another site to reach yours (excluding search engines and social, which are tracked separately).", category: "analytics" }),
  T({ term: "Multi-touch attribution", shortDef: "Crediting multiple touchpoints in a conversion.", definition: "Multi-touch attribution gives credit to multiple marketing touchpoints (e.g. blog post → newsletter → product page → signup). Models include linear, time-decay, position-based.", category: "analytics" }),
  T({ term: "First-touch attribution", shortDef: "Crediting the first touchpoint with the conversion.", definition: "First-touch attribution gives 100% of conversion credit to the first touchpoint a user had with your brand. Useful for understanding awareness-stage channels.", category: "analytics" }),
  T({ term: "Last-touch attribution", shortDef: "Crediting the last touchpoint with the conversion.", definition: "Last-touch attribution gives 100% of conversion credit to the touchpoint immediately before conversion. Default in many analytics tools but underestimates awareness channels.", category: "analytics" }),
  T({ term: "Goal", shortDef: "A defined conversion event in analytics.", definition: "A goal is a defined user action you want to track — signup, purchase, download. In GA4, goals are called conversion events.", category: "analytics" }),
  T({ term: "Heatmap", shortDef: "Visual map of where users click/scroll.", definition: "A heatmap visualizes user behavior — clicks, taps, scroll depth, mouse movement. Tools: Hotjar, Microsoft Clarity. Helps identify UX issues that analytics alone can't surface.", category: "analytics" }),
  T({ term: "Session replay", shortDef: "Recording of a user's session.", definition: "Session replay records and lets you watch a user's session — clicks, scrolls, form input. Combine with analytics to investigate drop-offs. Common tools: Hotjar, FullStory, Microsoft Clarity.", category: "analytics" }),

  // === MORE AI ===
  T({ term: "LLM", shortDef: "Large language model.", definition: "An LLM (Large Language Model) is a neural network trained on huge amounts of text to predict the next token. Examples: GPT-4, Claude, Gemini, Llama. Power chatbots, content generation, and AI search.", category: "ai" }),
  T({ term: "Embedding", shortDef: "Vector representation of text.", definition: "An embedding is a high-dimensional vector representing the meaning of a piece of text. Similar texts have similar vectors. Powers semantic search, RAG, and recommendation engines.", category: "ai" }),
  T({ term: "RAG", shortDef: "Retrieval-augmented generation.", definition: "RAG (Retrieval-Augmented Generation) is the technique of retrieving relevant documents and feeding them to an LLM as context before it generates an answer. Reduces hallucination and lets LLMs reference up-to-date or proprietary info.", category: "ai" }),
  T({ term: "Vector database", shortDef: "Database optimized for embedding similarity search.", definition: "A vector database stores embeddings and enables fast similarity search. Examples: Pinecone, Weaviate, Qdrant, Chroma, pgvector. Core infrastructure for RAG and semantic search.", category: "ai" }),
  T({ term: "Prompt engineering", shortDef: "Crafting prompts to get good LLM outputs.", definition: "Prompt engineering is the practice of crafting prompts to elicit specific behaviors from an LLM. Techniques: system prompts, few-shot examples, chain-of-thought, role-playing, structured outputs.", category: "ai" }),
  T({ term: "Hallucination", shortDef: "When an LLM invents incorrect facts.", definition: "Hallucination is when an LLM confidently outputs information that isn't true. Mitigations: RAG, grounding to sources, requiring citations, fine-tuning, lower temperature.", category: "ai" }),
  T({ term: "Fine-tuning", shortDef: "Adapting a pretrained model to a specific task.", definition: "Fine-tuning is training a pretrained model on a smaller, task-specific dataset. Used to specialize LLMs for a domain or style. More expensive than prompting; usually only worth it for high-volume production use cases.", category: "ai" }),
  T({ term: "RLHF", shortDef: "Reinforcement learning from human feedback.", definition: "RLHF (Reinforcement Learning from Human Feedback) is a training technique that uses human ratings to align model outputs with human preferences. Made ChatGPT possible.", category: "ai" }),
  T({ term: "AI Overview", shortDef: "Google's AI-generated answer at the top of SERPs.", definition: "AI Overviews (formerly SGE) are AI-generated summaries Google shows at the top of some search results, with citations. Major SEO disruption — clicks below the AI Overview drop significantly.", category: "ai" }),
  T({ term: "AI search", shortDef: "Search engines powered by LLMs.", definition: "AI search (Perplexity, ChatGPT search, Google AI Overviews, Bing Copilot) returns AI-generated answers with citations instead of just blue links. Optimizing for AI search is increasingly important — see LLM visibility.", category: "ai" }),
  T({ term: "AI referrer", shortDef: "Traffic coming from AI assistants.", definition: "AI referrers are visitors arriving from AI platforms — chat.openai.com, perplexity.ai, claude.ai. Track them separately to measure AI search ROI. RankFlo's analytics detects AI referrers automatically.", category: "ai" }),
  T({ term: "AI citation", shortDef: "When an AI answer references your content.", definition: "An AI citation is when ChatGPT, Perplexity, Claude, or another AI assistant references your content as a source in its answer. Drives qualified traffic and brand awareness.", category: "ai" }),
  T({ term: "llms.txt", shortDef: "File telling AI crawlers what your site is about.", definition: "llms.txt is a proposed file (like robots.txt) at /llms.txt that gives AI crawlers a structured summary of your site's content. Helps LLMs understand and reference your content accurately.", category: "ai" }),
  T({ term: "MCP", shortDef: "Model Context Protocol — standard for AI tool use.", definition: "MCP (Model Context Protocol) is an open standard from Anthropic for connecting AI assistants to data sources and tools. RankFlo ships an MCP server so Claude Desktop can manage your content directly.", category: "ai" }),
  T({ term: "Function calling", shortDef: "LLMs invoking tools/APIs.", definition: "Function calling (or tool use) lets LLMs invoke external functions or APIs — fetching live data, running calculations, calling databases. Powers AI agents and AI search.", category: "ai" }),
  T({ term: "AI agent", shortDef: "LLM-powered system that takes actions.", definition: "An AI agent is an LLM-based system that perceives, plans, and acts to accomplish a goal — not just generating text. Combines LLMs with tool use, memory, and orchestration.", category: "ai" }),
  T({ term: "ChatGPT", shortDef: "OpenAI's consumer AI assistant.", definition: "ChatGPT is OpenAI's consumer-facing AI assistant, powered by GPT-4 and successor models. Launched late 2022, kicked off the LLM mainstream wave. Major source of AI referrer traffic.", category: "ai" }),
  T({ term: "Claude", shortDef: "Anthropic's AI assistant.", definition: "Claude is Anthropic's AI assistant family (Claude 3, 3.5, etc.). Known for strong reasoning, longer context, and a focus on safety. Available via web, API, and integrations.", category: "ai" }),
  T({ term: "Perplexity", shortDef: "AI-powered search engine.", definition: "Perplexity is an AI-powered search engine that returns sourced, conversational answers. A major channel for content discovery alongside Google AI Overviews.", category: "ai" }),
  T({ term: "Gemini", shortDef: "Google's AI assistant.", definition: "Gemini is Google's AI assistant family, powering Google AI Overviews, Bard's successor, and the Gemini API. Multimodal (text, image, video, audio).", category: "ai" }),

  // === MORE TECHNICAL ===
  T({ term: "HTTPS", shortDef: "Encrypted HTTP.", definition: "HTTPS is HTTP over TLS — encrypts the connection between browser and server. Required for SEO ranking, trust, and most browser features. Free certificates available via Let's Encrypt.", category: "technical" }),
  T({ term: "SSL", shortDef: "Older name for TLS.", definition: "SSL (Secure Sockets Layer) is the predecessor to TLS. Modern HTTPS uses TLS, but \"SSL certificate\" is still the common term for the cert that powers HTTPS.", category: "technical" }),
  T({ term: "TLS", shortDef: "Transport layer security.", definition: "TLS (Transport Layer Security) is the cryptographic protocol that powers HTTPS, secure email, and many other protocols. Current widely-used version is TLS 1.3.", category: "technical" }),
  T({ term: "CDN", shortDef: "Content delivery network.", definition: "A CDN (Content Delivery Network) caches your content at edge servers around the world, serving users from the closest location. Improves performance and Core Web Vitals.", category: "technical" }),
  T({ term: "Reverse proxy", shortDef: "Server sitting in front of your app.", definition: "A reverse proxy (nginx, Caddy, Cloudflare) sits between users and your app server. Handles HTTPS termination, caching, load balancing, and basic security.", category: "technical" }),
  T({ term: "Critical CSS", shortDef: "Above-the-fold CSS inlined for fast render.", definition: "Critical CSS is the minimal CSS needed to render the visible portion of a page. Inlining it in <head> avoids a render-blocking CSS request and improves LCP.", category: "technical" }),
  T({ term: "Lazy loading", shortDef: "Deferring image/iframe loading until visible.", definition: "Lazy loading defers loading of images, iframes, or scripts until they're about to enter the viewport. Use loading=\"lazy\" attribute. Improves initial page load metrics.", category: "technical" }),
  T({ term: "Preload", shortDef: "Tell browser to fetch a resource early.", definition: "<link rel=\"preload\"> tells the browser to fetch a critical resource (font, hero image) early, before its discovery in HTML. Use sparingly — overuse hurts performance.", category: "technical" }),
  T({ term: "Prefetch", shortDef: "Hint browser to fetch resources for likely-next pages.", definition: "<link rel=\"prefetch\"> hints the browser to fetch resources during idle time for pages the user is likely to visit next. Lower priority than preload.", category: "technical" }),
  T({ term: "Service worker", shortDef: "Browser background script for caching/offline.", definition: "A service worker is a JavaScript file that runs in the background, separate from the page. Powers offline support, push notifications, and advanced caching strategies. Foundation of PWAs.", category: "technical" }),
  T({ term: "PWA", shortDef: "Progressive web app.", definition: "A PWA (Progressive Web App) is a website that uses service workers, a manifest, and modern browser APIs to feel like a native app — installable, offline-capable, push-enabled.", category: "technical" }),

  // === MORE MARKETING ===
  T({ term: "SaaS", shortDef: "Software as a service.", definition: "SaaS (Software as a Service) is software delivered over the internet on a subscription model. Massive category, dominated by recurring revenue and product-led growth.", category: "marketing" }),
  T({ term: "B2B", shortDef: "Business-to-business.", definition: "B2B (Business-to-Business) describes companies that sell to other businesses. B2B marketing typically has longer sales cycles, higher LTV, and content-heavy funnels.", category: "marketing" }),
  T({ term: "B2C", shortDef: "Business-to-consumer.", definition: "B2C (Business-to-Consumer) describes companies that sell directly to end consumers. Shorter sales cycles, higher transaction volume, more reliance on emotional/visual marketing.", category: "marketing" }),
  T({ term: "ICP", shortDef: "Ideal customer profile.", definition: "An ICP (Ideal Customer Profile) is a description of the perfect-fit customer for your product — firmographics, needs, behaviors. Sharpens targeting and messaging.", category: "marketing" }),
  T({ term: "MQL", shortDef: "Marketing qualified lead.", definition: "An MQL (Marketing Qualified Lead) is a lead deemed ready for sales follow-up based on engagement and fit signals. Definition varies by company.", category: "marketing" }),
  T({ term: "SQL (sales)", shortDef: "Sales qualified lead.", definition: "An SQL (Sales Qualified Lead) is a lead validated by sales as a real opportunity. Comes after MQL in the typical B2B funnel.", category: "marketing" }),
  T({ term: "CAC", shortDef: "Customer acquisition cost.", definition: "CAC (Customer Acquisition Cost) is the total cost to acquire one customer — typically marketing + sales spend divided by new customers. Should be much lower than LTV.", category: "marketing" }),
  T({ term: "LTV", shortDef: "Customer lifetime value.", definition: "LTV (Lifetime Value) is the total revenue you expect from a customer over their lifetime. Healthy SaaS businesses have LTV:CAC ratios of 3:1 or higher.", category: "marketing" }),
  T({ term: "ARR", shortDef: "Annual recurring revenue.", definition: "ARR (Annual Recurring Revenue) is the predictable yearly subscription revenue. Core SaaS metric. Calculated as MRR × 12.", category: "marketing" }),
  T({ term: "MRR", shortDef: "Monthly recurring revenue.", definition: "MRR (Monthly Recurring Revenue) is the predictable monthly subscription revenue. Tracks growth, churn, and expansion month-over-month.", category: "marketing" }),
  T({ term: "Churn", shortDef: "Rate of customers leaving.", definition: "Churn is the rate at which customers cancel. Measured monthly or annually. Logo churn (count) and revenue churn (dollars) tell different stories.", category: "marketing" }),
  T({ term: "Retention", shortDef: "% of customers who keep paying.", definition: "Retention is the inverse of churn — the % of customers who keep paying. Net retention (including expansion) above 100% is the holy grail of SaaS.", category: "marketing" }),
  T({ term: "NPS", shortDef: "Net promoter score.", definition: "NPS (Net Promoter Score) measures customer loyalty: \"How likely are you to recommend us?\" on a 0–10 scale. Promoters (9–10) minus detractors (0–6) = NPS.", category: "marketing" }),
  T({ term: "Drip campaign", shortDef: "Automated sequence of emails over time.", definition: "A drip campaign is a series of automated emails sent on a schedule or triggered by user actions. Common for onboarding, lead nurturing, and re-engagement.", category: "marketing" }),
  T({ term: "Cold email", shortDef: "Outbound email to a non-subscriber.", definition: "Cold email is outbound email sent to people who haven't opted in. Effective when highly targeted and value-led; spammy when not. Subject to anti-spam regulations (CAN-SPAM, GDPR).", category: "marketing" }),
]);

export const ALL_GLOSSARY_SLUGS = Object.keys(GLOSSARY);

